insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('fest-cuautitlan-2022', 'Festejando Cuautitlán 2022', 'festival_municipal', '2022-08-16', '2022-08-23', 15, 20, 1.25, 0.95, 'verificado', 'https://www.milenio.com/politica/comunidad/cuautitlan-celebra-aniversario-fundacion-actividades-fechas', 'Fuera del rango de datos simulados (antes de 2025-01-01) — se carga por completitud del calendario, no afecta el re-horario ni el generador.') on conflict (id) do nothing;
insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('fest-cuautitlan-2023', 'Festejando Cuautitlán 2023 (199° aniversario)', 'festival_municipal', '2023-08-16', '2023-08-23', 15, 20, 1.25, 0.95, 'verificado', 'https://www.dondehayferia.com/semana-cultural-y-artistica-cuautitlan-2023', 'Semana Cultural y Artística 2023, 199° aniversario. Verificado en Fase 2.2 (el enunciado lo marcaba ''patrón, VERIFICAR'').') on conflict (id) do nothing;
insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('fest-cuautitlan-2024', 'Festejando Cuautitlán 2024', 'festival_municipal', '2024-08-16', '2024-08-23', 15, 20, 1.25, 0.95, 'patron', null, 'No se encontró cobertura de prensa específica de 2024 en la búsqueda de Fase 2.2 — se mantiene como patrón (16-23 ago, igual que 2022/2023/2025), sin degradar ni promover.') on conflict (id) do nothing;
insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('fest-cuautitlan-2025', 'Festejando Cuautitlán 2025', 'festival_municipal', '2025-08-16', '2025-08-23', 15, 20, 1.25, 0.95, 'verificado', 'https://www.unotv.com/entretenimiento/festival-de-cuautitlan-2025-fechas-y-artistas-por-dia/', null) on conflict (id) do nothing;
insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('fest-cuautitlan-2026', 'Festejando Cuautitlán 2026 (202° aniversario)', 'festival_municipal', '2026-08-12', '2026-08-16', 15, 20, 1.25, 0.95, 'verificado', 'https://www.infobae.com/mexico/2026/08/05/conciertos-gratis-en-el-festival-de-cuautitlan-2026-dld-los-cardenales-de-nuevo-leon-y-rayito-colombiano-en-el-programa/', 'CORRIGE el dato del enunciado: no fueron 6 días "por confirmar" — fueron 5 noches, 12-16 de agosto (no 16-23), cierre el domingo 16 coincidiendo con la fecha de fundación. Confirmado con 4 fuentes mayores (Infobae, Heraldo de México Edomex, Milenio, Capital Edomex). El patrón 16-23 NO se repitió en 2026 — el festival se movió a fechas más tempranas y se acortó. Reportado al usuario en el resumen de Fase 2.
insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('pista-hielo-2025-2026', 'Pista de hielo navideña — Concha Acústica, Parque de la Cruz', 'temporada_navidena', '2025-12-16', '2026-01-10', 15, 20, 1.2, 1.0, 'verificado', 'https://www.mediotiempo.com/actualidad/comunidad/pistas-de-hielo-en-cdmx-y-edomex-2025-guia-definitiva-para-patinar-esta-navidad', 'Inicio (16 dic, tras la posada navideña municipal) verificado con varias fuentes locales (parrafo1224.com.mx, vocesmexiquenses.com, mediotiempo.com). La fecha de CIERRE no se pudo verificar con certeza: las fuentes discrepan entre 5, 10 y 11 de enero de 2026 — se usa 10 de enero como punto medio, marcado como patrón, no verificado, dentro del mismo registro (ver fin_confianza).
insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('tianguis-martes', 'Tianguis de los martes (La Palma / Prolongación)', 'tianguis_semanal', '2025-01-01', '2026-12-31', 6, 14, 1.08, 1.0, 'verificado', 'https://cuautitlan.gob.mx/publico/Cronicas/EL%20IMBATIBLE%20TIANGUIS%20DE%20LOS%20MARTES.pdf', 'No está en el centro (La Palma y Prolongación), efecto de goteo supuesto.') on conflict (id) do nothing;
insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('tianguis-muertos', 'Tianguis de Día de Muertos (junto al mercado municipal)', 'tianguis_temporada', '2025-10-30', '2025-11-02', 9, 18, 1.1, 1.0, 'supuesto', null, 'Degradado de ''existencia verificada'' (como decía el enunciado) a supuesto: la búsqueda de Fase 2.2 solo confirmó tianguis de Muertos en Cuautitlán IZCALLI y en Cuautla (municipios distintos) — ninguna fuente específica de Cuautitlán propio. Sí existe evidencia de tradición de tianguis semanal en Cuautitlán (ver tianguis-martes), lo que hace plausible un tianguis de temporada, pero no se encontró confirmación directa.
insert into bd_eventos_locales (id, nombre, tipo, inicio, fin, hora_inicio_efecto, hora_fin_efecto, mult_local, mult_delivery, confianza, fuente_url, observacion) values ('tianguis-navideno', 'Tianguis / Bazar navideño (junto al mercado municipal)', 'tianguis_temporada', '2025-12-01', '2025-12-24', 9, 20, 1.1, 1.0, 'supuesto', null, 'Igual que tianguis-muertos: no se encontró una fuente específica y citable de Cuautitlán propio en la búsqueda de Fase 2.2 (hay referencias genéricas a un "Bazar Navideño" organizado por el Mercado Municipal, sin URL limpia que lo confirme) — se deja como supuesto en vez de verificado/patrón.
